sp_widget.css:
/* ===================================
   HERO
=================================== */

.automed-hero{

    position:relative;

    overflow:hidden;

    border-radius:24px;

    padding:45px;

    color:white;

    background:linear-gradient(
        -45deg,
        #2563eb,
        #3b82f6,
        #4f46e5,
        #6366f1
    );

    background-size:400% 400%;

    animation:gradientMove 12s ease infinite;

    box-shadow:
        0 20px 40px rgba(37,99,235,.25);
}

@keyframes gradientMove{

    0%{
        background-position:0% 50%;
    }

    50%{
        background-position:100% 50%;
    }

    100%{
        background-position:0% 50%;
    }
}

/* ===================================
   BACKGROUND OVERLAY
=================================== */

.hero-overlay{

    position:absolute;

    inset:0;

    background:
        radial-gradient(
            rgba(255,255,255,.15) 2px,
            transparent 2px
        );

    background-size:35px 35px;

    opacity:.4;
}

/* ===================================
   FLOATING ICONS
=================================== */

.floating-icon{

    position:absolute;

    color:rgba(255,255,255,.08);

    z-index:1;
}

.icon1{
    top:10%;
    left:8%;
    font-size:60px;
    animation:float1 6s infinite ease-in-out;
}

.icon2{
    top:20%;
    right:10%;
    font-size:75px;
    animation:float2 8s infinite ease-in-out;
}

.icon3{
    bottom:10%;
    right:15%;
    font-size:90px;
    animation:float1 7s infinite ease-in-out;
}

.icon4{
    top:60%;
    left:12%;
    font-size:55px;
    animation:float2 9s infinite ease-in-out;
}

.icon5{
    top:40%;
    right:35%;
    font-size:70px;
    animation:float1 10s infinite ease-in-out;
}

@keyframes float1{

    0%{
        transform:translateY(0px);
    }

    50%{
        transform:translateY(-20px);
    }

    100%{
        transform:translateY(0px);
    }
}

@keyframes float2{

    0%{
        transform:translateY(0px) rotate(0deg);
    }

    50%{
        transform:translateY(-15px) rotate(8deg);
    }

    100%{
        transform:translateY(0px) rotate(0deg);
    }
}

/* ===================================
   PULSE RINGS
=================================== */

.pulse-ring{

    position:absolute;

    border:2px solid rgba(255,255,255,.15);

    border-radius:50%;

    animation:pulseRing 6s infinite;
}

.pulse1{

    width:350px;
    height:350px;

    right:-80px;
    top:-80px;
}

.pulse2{

    width:250px;
    height:250px;

    left:-50px;
    bottom:-50px;
}

@keyframes pulseRing{

    0%{
        transform:scale(1);
        opacity:.4;
    }

    50%{
        transform:scale(1.1);
        opacity:.15;
    }

    100%{
        transform:scale(1);
        opacity:.4;
    }
}

/* ===================================
   CONTENT
=================================== */

.automed-hero-inner{

    position:relative;

    z-index:10;
}

/* ===================================
   BADGE
=================================== */

.portal-badge{

    display:inline-block;

    padding:8px 18px;

    border-radius:50px;

    background:rgba(255,255,255,.15);

    backdrop-filter:blur(15px);

    border:1px solid rgba(255,255,255,.15);

    margin-bottom:20px;

    font-weight:600;
}

/* ===================================
   TEXT
=================================== */

.automed-hero h1{

    margin:0 0 15px;

    font-size:42px;

    font-weight:700;
}

.hero-subtitle{

    font-size:20px;

    margin-bottom:10px;

    opacity:.95;
}

.hero-description{

    max-width:700px;

    line-height:1.8;

    opacity:.9;

    margin-bottom:30px;
}

/* ===================================
   STATS
=================================== */

.hero-stats{

    display:flex;

    gap:18px;

    flex-wrap:wrap;
}

.stat-box{

    min-width:170px;

    background:rgba(255,255,255,.12);

    backdrop-filter:blur(16px);

    border:1px solid rgba(255,255,255,.15);

    border-radius:18px;

    padding:18px 25px;

    transition:.35s;
}

.stat-box:hover{

    transform:
        translateY(-6px)
        scale(1.03);

    background:rgba(255,255,255,.20);
}

.stat-number{

    display:block;

    font-size:32px;

    font-weight:700;
}

.stat-label{

    font-size:13px;

    text-transform:uppercase;

    letter-spacing:1px;

    opacity:.9;
}

/* ===================================
   MOBILE
=================================== */

@media(max-width:768px){

    .automed-hero{

        padding:25px;
    }

    .automed-hero h1{

        font-size:28px;
    }

    .hero-stats{

        flex-direction:column;
    }

    .floating-icon{
        display:none;
    }

    .pulse-ring{
        display:none;
    }
}

sp_widget.script:
(function() {

    data.user_name = gs.getUser().getFirstName();

    var hour = parseInt(
        new GlideDateTime()
        .getLocalTime()
        .getByFormat("HH")
    );

    if(hour < 12)
        data.greeting = "Good Morning";
    else if(hour < 17)
        data.greeting = "Good Afternoon";
    else
        data.greeting = "Good Evening";

    // Replace these with actual GlideRecord counts later
    data.due_today = 5;
    data.patient_count = 12;

})();
